      CodexPageConnection: { type: "object", additionalProperties: false, description: "One row of a page's Connections panel: the OTHER endpoint resolved, plus which way the edge points. Folds in what used to be two separate views (backlinks and typed relationships).", required: ["id", "direction", "otherKind", "otherId", "otherTitle", "otherEntityType", "otherRevealed", "label", "origin", "layer", "section"], properties: { id: codexNullableUuid, direction: { type: "string", enum: ["out", "in"] }, otherKind: { type: "string", enum: ["page", "session", "quest", "journal"] }, otherId: codexUuid, otherTitle: { type: "string", description: "A page title, \"Session 4\", a quest title, or a bounded excerpt of a journal entry's player text - the reveal-audit naming rule." }, otherEntityType: { oneOf: [codexEntityType, { type: "null" }], description: "Pages only; null for every other kind." }, otherRevealed: { type: "boolean", description: "GM-only; not declared on `CodexPageConnectionPlayer` (a player only ever receives connections to records they can see)." }, label: { type: ["string", "null"] }, origin: { type: "string", enum: ["declared", "mention"] }, layer: { type: "string", enum: ["player", "gm"] }, section: { type: ["string", "null"], description: "The heading the mention sits under; null for a declared connection." } } },
      CodexPageConnectionPlayer: { type: "object", additionalProperties: false, description: "A page's Connections panel as a PLAYER receives it: revealed others only, so `otherRevealed` would be a constant, and no `id` or `layer`.", required: ["direction", "otherKind", "otherId", "otherTitle", "otherEntityType", "label", "origin", "section"], properties: { direction: { type: "string", enum: ["out", "in"] }, otherKind: { type: "string", enum: ["page", "session", "quest", "journal"] }, otherId: codexUuid, otherTitle: { type: "string" }, otherEntityType: { oneOf: [codexEntityType, { type: "null" }] }, label: { type: ["string", "null"] }, origin: { type: "string", enum: ["declared", "mention"] }, section: { type: ["string", "null"] } } },
